package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_clone_TriageGen1Test {

    @Test
    public void testCloneSimpleElement() {
        Element original = Parser.parseBodyFragment("<div id=\"test\" class=\"foo\">Hello</div>").body().child(0);
        Element cloned = original.clone();

        // Verify identity
        Assert.assertNotSame("Clone should be a different object instance", original, cloned);

        // Verify properties
        Assert.assertEquals("Tag name should match", original.tagName(), cloned.tagName());
        Assert.assertEquals("ID should match", original.id(), cloned.id());
        Assert.assertEquals("Class name should match", original.className(), cloned.className());
        Assert.assertEquals("Text content should match", original.text(), cloned.text());

        // Verify deep copy (attributes)
        Assert.assertEquals("Attribute 'id' should match", original.attr("id"), cloned.attr("id"));
    }

    @Test
    public void testCloneWithChildren() {
        Element original = Parser.parseBodyFragment("<div><p><span>Text</span></p></div>").body().child(0);
        Element cloned = original.clone();

        Assert.assertNotSame(original, cloned);
        Assert.assertEquals("Child count should match", original.children().size(), cloned.children().size());

        Element originalChild = original.child(0);
        Element clonedChild = cloned.child(0);

        Assert.assertNotSame("Children should be new instances", originalChild, clonedChild);
        Assert.assertEquals("Child tag name should match", originalChild.tagName(), clonedChild.tagName());

        Element originalGrandChild = originalChild.child(0);
        Element clonedGrandChild = clonedChild.child(0);

        Assert.assertNotSame("Grandchildren should be new instances", originalGrandChild, clonedGrandChild);
        Assert.assertEquals("Grandchild text should match", originalGrandChild.text(), clonedGrandChild.text());
    }

    @Test
    public void testCloneWithAttributesAndDataset() {
        Element original = new Element(org.jsoup.parser.Tag.valueOf("div"), "");
        original.attr("data-id", "123");
        original.attr("class", "container");
        original.attr("custom-attr", "value");

        Element cloned = original.clone();

        Assert.assertEquals("data-id should match", "123", cloned.attr("data-id"));
        Assert.assertEquals("class should match", "container", cloned.className());
        Assert.assertEquals("custom-attr should match", "value", cloned.attr("custom-attr"));
        Assert.assertEquals("Dataset should match", original.dataset(), cloned.dataset());
    }

    @Test
    public void testCloneEmptyElement() {
        Element original = new Element(org.jsoup.parser.Tag.valueOf("br"), "");
        Element cloned = original.clone();

        Assert.assertEquals(original.tagName(), cloned.tagName());
        Assert.assertTrue("Cloned empty element should have no children", cloned.children().isEmpty());
    }

    @Test
    public void testCloneDeepIntegrity() {
        // Testing that changing the clone does not affect the original
        Element original = Parser.parseBodyFragment("<div class=\"orig\"><span class=\"inner\">Text</span></div>").body().child(0);
        Element cloned = original.clone();

        cloned.attr("class", "modified");
        cloned.child(0).text("Changed");

        Assert.assertNotEquals("Original class should not change", "orig", original.className());
        Assert.assertEquals("Original class should remain", "orig", original.className());
        Assert.assertEquals("Original text should remain", "Text", original.child(0).text());
        Assert.assertNotEquals("Cloned text should be changed", "Text", cloned.child(0).text());
    }
}
